const geometryCache = new Map();

/**
 * Normalize any crop name string into supported crop keys:
 * 'rice', 'wheat', 'tomato', 'maize', 'potato', 'cotton'
 */
export function normalizeCropKey(rawCropName) {
  if (!rawCropName) return 'wheat';
  const s = String(rawCropName).toLowerCase().trim();
  if (s.includes('rice') || s.includes('paddy')) return 'rice';
  if (s.includes('wheat')) return 'wheat';
  if (s.includes('tomato')) return 'tomato';
  if (s.includes('maize') || s.includes('corn')) return 'maize';
  if (s.includes('potato') || s.includes('beet') || s.includes('tuber')) return 'potato';
  if (s.includes('cotton')) return 'cotton';
  return 'wheat';
}

/**
 * Returns a high-fidelity THREE.BufferGeometry for the requested crop and growth stage.
 * @param {string} cropName - 'Rice', 'Wheat', 'Tomato', 'Maize', 'Potato', 'Cotton'
 * @param {number} stageIndex - Growth stage index (0 to 5)
 * @returns {THREE.BufferGeometry}
 */
export function getCropGeometry(cropName, stageIndex = 2) {
  const cropKey = normalizeCropKey(cropName);
  
  // Map 6 growth stages to available 4 3D models:
  // 0 (Sowing) -> 1 (Sprout)
  // 1 (Germination/Seedling) -> 1 (Sprout)
  // 2 (Vegetative/Tillering) -> 2 (Young Plant)
  // 3 (Flowering/Booting) -> 3 (Flowering/Maturing)
  // 4 (Fruiting/Grain Fill) -> 4 (Full Crop with Fruits/Ears)
  // 5 (Harvest Ripe) -> 4 (Full Crop with Fruits/Ears)
  let stageNum = 2;
  if (stageIndex <= 1) stageNum = 1;
  else if (stageIndex === 2) stageNum = 2;
  else if (stageIndex === 3) stageNum = 3;
  else stageNum = 4;

  const cacheKey = `${cropKey}_stage_${stageNum}`;
  if (geometryCache.has(cacheKey)) {
    return geometryCache.get(cacheKey);
  }

  const cropData = RAW_CROP_DATA[cropKey] || RAW_CROP_DATA['wheat'];
  const stageData = cropData[stageNum] || cropData[4] || cropData[2];

  if (!stageData || !stageData.p || stageData.p.length === 0) {
    const fallback = new THREE.CylinderGeometry(0.08, 0.12, 1.2, 5);
    geometryCache.set(cacheKey, fallback);
    return fallback;
  }

  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.Float32BufferAttribute(stageData.p, 3));
  if (stageData.c && stageData.c.length === stageData.p.length) {
    geo.setAttribute('color', new THREE.Float32BufferAttribute(stageData.c, 3));
  }
  geo.computeVertexNormals();
  geo.computeBoundingSphere();
  geo.computeBoundingBox();

  geometryCache.set(cacheKey, geo);
  return geo;
}

export function createCropMaterial() {
  return new THREE.MeshStandardMaterial({
    vertexColors: true,
    roughness: 0.60,
    metalness: 0.05,
    side: THREE.DoubleSide
  });
}
